// Strict Input Contract Enforcement
const order = $input.item.json;

if (!order || typeof order !== "object") {
  throw new Error("CONTRACT_VIOLATION: Empty or invalid payload delivered to Tax Sub-Workflow");
}
if (!order.state) {
  throw new Error("CONTRACT_VIOLATION: Missing required parameter 'state'");
}
if (order.subtotal === undefined || typeof order.subtotal !== "number") {
  throw new Error("CONTRACT_VIOLATION: Missing or invalid numerical 'subtotal'");
}

const stateRates = {
  "CA": 0.0825,
  "NY": 0.08875,
  "TX": 0.0625,
  "FL": 0.0600,
  "IL": 0.0625
};

const rate = stateRates[order.state] || 0.0500; // 5% default fallback
const subtotal = Number(order.subtotal || 0);
const taxAmount = Number((subtotal * rate).toFixed(2));
const grandTotal = Number((subtotal + taxAmount).toFixed(2));

return {
  json: {
    orderId: order.orderId || "ORD-ANONYMOUS",
    subtotal: subtotal,
    state: order.state,
    appliedTaxRate: rate,
    taxAmount: taxAmount,
    grandTotal: grandTotal,
    status: "CALCULATED_REMOTE",
    taxEngineVersion: "v2.4-enterprise"
  }
};
